body_md:
A nonnegative $(\mathcal F_t)_{t\ge0}$-adapted process
		$A=(A_t)_{t\ge0}$ is called a \emph{positive continuous additive functional}
		(PCAF) of $Y$ if $A_0=0$ and, under every admissible starting law, its paths
		are almost surely continuous and nondecreasing, and satisfy
		\begin{equation}
			\label{eq:PCAF-additivity}
			A_{t+s}
			=
			A_t+A_s\circ\theta_t,
			\qquad s,t\ge0.
		\end{equation}

\label{lem:AF-conditioning}
		Let \(F\) be a nonnegative measurable functional of the future base path such that
		\[
		K:=\sup_{z\in E}\operatorname{E}_z F<\infty.
		\]
		For deterministic $0\le a\le b$,
		\begin{equation}\label{eq:AF-conditioning}
			\operatorname{E}_y\int_a^b F\circ\theta_s\,dA_s
			\le K\operatorname{E}_y(A_b-A_a).
		\end{equation}
		Moreover, for every integer $p\ge1$,
		\begin{equation}\label{eq:abstract-A-moment}
			\sup_y\operatorname{E}_y A_t^p\le p!M(t)^p\le p!C_T^pt^{p\vartheta}.
		\end{equation}
		For every finite real $q\ge1$ this implies
		\begin{equation}\label{eq:abstract-A-increments}
			\sup_y\operatorname{E}_y(A_v-A_u)^q\le C_{T,q}(v-u)^{q\vartheta},
			\qquad 0\le u<v\le T.
		\end{equation}

\label{thm:abstract-averaging}
		Assume \eqref{eq:abstract-A-first}. The following estimates hold uniformly in the initial states $y\in E$ and $i\in S$, for $0<\varepsilon\le1$.
		\begin{enuroman}
			\item\label{item:abstract-random-time}
			For every $[0,T]$-valued random time $\tau$ measurable with respect to the base path,
			\begin{equation}\label{eq:abstract-random-time}
				\operatorname{E}_{y,i}|J_\varepsilon(\tau)|^2\le C_{T,h}\varepsilon^\vartheta.
			\end{equation}
			No stopping-time property is required. Once the base path is fixed,
			both $dA$ and the upper limit $\tau$ are deterministic from the point of
			view of the chain.
			\item\label{item:abstract-max}
			The uniform estimate is
			\begin{equation}\label{eq:abstract-max}
				\operatorname{E}_{y,i}\sup_{0\le t\le T}|J_\varepsilon(t)|^2
				\le C_{T,h}\varepsilon^\vartheta(1+|\log\varepsilon|)^2.
			\end{equation}
			In particular, $J_\varepsilon\to0$ in $L^2$ for the uniform norm on $C([0,T])$ under every starting law, uniformly in the starting states.
		\end{enuroman}

\label{cor:abstract-all-moments}
		Under \eqref{eq:abstract-A-first}, for every $0<\zeta<\vartheta$, 
		\begin{equation}\label{eq:abstract-all-moments-max}
			\sup_{y,i}\operatorname{E}_{y,i}\sup_{t\le T}|J_\varepsilon(t)|^2
			\le C_{T,h,\zeta}\varepsilon^\zeta.
		\end{equation}
		Here, the constant depends on $\zeta $ and the limit exponent $\vartheta $ is not attained.

\label{prop:time_change0}
		Let $f\in C(\overline D)$ and define $u$ by
		\begin{equation}
			u(t,x) := \operatorname{E}_x  \left[{f(W^{(\rho,\kappa)}_t)}\right] , \quad t \ge 0, \; x\in D.
		\end{equation}
		Then $u$ admits the representation
		\begin{equation}
			\label{eq:semigroup}
			u(t,x) = \operatorname{E}_{x}  \left[{f(W^{+}_{\gamma(t)}) e^{-\kappa L^{}_{\gamma(t)}(W^+)}}\right] , \quad t \ge 0, \; x\in D.
		\end{equation}

If $\kappa=0$, \eqref{eq:semigroup} reduces to
		\begin{equation}
			\operatorname{E}_x  \left[{f(W^{(\rho)}_t)}\right]  = \operatorname{E}_{x}  \left[{f(W^{+}_{\gamma(t)}) }\right] , 
		\end{equation}
		so $W^{(\rho)}$ and $W^{+}_{\gamma(\cdot)}$ have the same law.
		More generally, for $\kappa\in[0,\infty)$, the semigroups of $W^{(\rho,\kappa)}$, $W^{(\rho)}$, and $W^+$ are linked by the identity
		\begin{equation}
			\operatorname{E}_x  \left[{f(W^{(\rho,\kappa)}_t)}\right]  = \operatorname{E}_{x}  \left[{f(W^{(\rho)}_{t}) e^{-\kappa L^{}_{t}(W^{(\rho)})}}\right] 
			= \operatorname{E}_{x}  \left[{f(W^{+}_{\gamma(t)}) e^{-\kappa L^{}_{\gamma(t)}(W^+)}}\right]  , \quad t \ge 0, \; x\in D.
		\end{equation}

\label{thm:SE_homogenization_1}
		For every bounded Lipschitz function
		\(f:\overline D\to\mathbb R\) and every time horizon \(T>0\), the following estimates hold.
		\begin{enuroman}
			\item \label{item:marginal}
			For every \(0<\beta<1/8\), there exists
			\(C=C(f,T,\beta)>0\), independent of \(\varepsilon\), such that
			\begin{equation}
				\label{eq:semigroup-rate-nonmax}
				\sup_{x\in\overline D} \sup_{0\le t\le T}
				\operatorname{E}^\alpha\left[
				|u^\varepsilon_\alpha(t,x)-u^0(t,x)|
				\right]
				\le
				C\varepsilon^\beta.
			\end{equation}

			\item \label{item:sup}
			For every \(0<\beta<1/8\), there exists
			\(C=C(f,T,\beta)>0\), independent of \(\varepsilon\), such that
			\begin{equation}
				\label{eq:semigroup-rate}
				\sup_{x\in\overline D} \operatorname{E}^\alpha\left[
				\sup_{0\le t\le T}
				|u^\varepsilon_\alpha(t,x)-u^0(t,x)|
				\right]
				\le
				C\varepsilon^\beta.
			\end{equation}
		\end{enuroman}

		Consequently, for every \(x\in\overline D\), Markov's inequality yields
		\[
		\sup_{0\le t\le T}
		|u^\varepsilon_\alpha(t,x)-u^0(t,x)|
		\longrightarrow 0
		\qquad\text{in }\operatorname{P}^\alpha\text{-probability}.
		\]
		Hence, for every fixed \(t\in[0,T]\),
		\[
		u^\varepsilon_\alpha(t,x)
		\longrightarrow
		u^0(t,x)
		\qquad\text{in }\operatorname{P}^\alpha\text{-probability}.
		\]

\label{thm:sticky}
		For every \(p\in[1,2]\) and every \(T>0\), the following estimates hold.
		\begin{enuroman}
			\item \label{item:sticky_marginal}
			For every \(0<\beta<1/8\), there exists
			\(C=C(p,T,\beta)>0\), independent of \(\varepsilon\), such that
			\begin{equation}
				\label{eq:fixed-time-process-rate}
				\sup_{x\in\overline D} \sup_{0\le t\le T}
				\operatorname{E}_{x,\pi}\left[
				|\widetilde X^\varepsilon_t-\widetilde X^0_t|^p
				\right]^{1/p}
				\le
				C\varepsilon^{\beta}.
			\end{equation}

			\item \label{item:sticky_uniform}
			For every \(0<\beta<1/8\), there exists
			\(C=C(p,T,\beta)>0\), independent of \(\varepsilon\), such that
			\begin{equation}
				\label{eq:uniform-process-rate}
				\sup_{x\in\overline D} \operatorname{E}_{x,\pi}\left[
				\sup_{t\in[0,T]}
				|\widetilde X^\varepsilon_t-\widetilde X^0_t|^p
				\right]^{1/p}
				\le
				C\varepsilon^\beta.
			\end{equation}
		\end{enuroman}

		In particular, both estimates imply the corresponding convergence
		in probability by Markov's inequality.

Throughout the proof, \(C\) may change from line to line but is independent
	of \(\varepsilon\) and uniform in \(x\in\overline D\).

	\medskip\noindent\emph{Step 1: control of the clocks.}
	Set
	\begin{equation}
		\label{eq:Delta_epsilon}
		\Delta_\varepsilon(t)
		:=
		|\gamma_\varepsilon(t)-\gamma_0(t)|.
	\end{equation}
	Since \(A_\varepsilon(r)\ge r\) and \(A_0(r)\ge r\),
	\[
	\gamma_\varepsilon(t),\gamma_0(t)\le t\le T.
	\]
	Moreover,
	\[
	A_\varepsilon(b)-A_\varepsilon(a)
	=
	(b-a)+\int_a^b\rho(\alpha_{s/\varepsilon})\,dL_s
	\ge b-a,
	\]
	so \(\gamma_\varepsilon=A_\varepsilon^{-1}\) is \(1\)-Lipschitz.

	Taking \(y=\gamma_0(t)\) yields \(A_0(y)=t\) and
	\begin{equation}
		\label{eq:fixed-time-inverse-bound}
		\begin{aligned}
			\Delta_\varepsilon(t)
			&=
			|\gamma_\varepsilon(t)-\gamma_\varepsilon(A_\varepsilon(y))|\\
			&\le
			|A_0(y)-A_\varepsilon(y)|\\
			&=
			\left|
			\int_0^{\gamma_0(t)}
			\bigl(\rho(\alpha_{s/\varepsilon})-\overline\rho\bigr)\,dL_s
			\right|.
		\end{aligned}
	\end{equation}
	Since \(\gamma_0(t)\) depends only on the reflected path and is bounded by
	\(T\), the random-time averaging estimate
	\eqref{eq:local-time-averaging-assumption-nonmax}, which is uniform in the
	starting point, gives
	\begin{equation}
		\label{eq:fixed-time-gamma-L2-rate}
		\sup_{x\in\overline D}
		\sup_{0\le t\le T}
		\operatorname{E}_{x,\pi}\left[\Delta_\varepsilon(t)^2\right]
		\le
		C\varepsilon^{1/2}.
	\end{equation}
	Hence, by Lyapunov's inequality, for every \(a\in(0,2]\),
	\begin{equation}
		\label{eq:fixed-time-gamma-La-rate}
		\sup_{x\in\overline D}
		\sup_{0\le t\le T}
		\operatorname{E}_{x,\pi}\left[\Delta_\varepsilon(t)^a\right]
		\le
		C\varepsilon^{a/4}.
	\end{equation}

	\medskip
	\noindent\emph{Step 2: fixed-time spatial error.}
	Fix \(\theta\in(0,1/2)\). The H\"older seminorm gives
	\[
	\left|
	W^+_{\gamma_\varepsilon(t)}
	-
	W^+_{\gamma_0(t)}
	\right|
	\le
	[W^+]_{\theta,T}
	|\gamma_\varepsilon(t)-\gamma_0(t)|^\theta
	=
	[W^+]_{\theta,T}\Delta_\varepsilon(t)^\theta.
	\]
	Choose \(q>1\) so close to \(1\) that \(p\theta q\le2\), and let \(q'\) be its
	conjugate exponent. H\"older's inequality gives
	\begin{align}
		\operatorname{E}_{x,\pi}\left[
		\left|
		W^+_{\gamma_\varepsilon(t)}
		-
		W^+_{\gamma_0(t)}
		\right|^p
		\right]
		&\le
		\operatorname{E}_{x,\pi}\left[
		[W^+]_{\theta,T}^p
		\Delta_\varepsilon(t)^{p\theta}
		\right]
		\\
		&\le
		\operatorname{E}_x^W\left[[W^+]_{\theta,T}^{pq'}\right]^{1/q'}
		\operatorname{E}_{x,\pi}\left[
		\Delta_\varepsilon(t)^{p\theta q}
		\right]^{1/q}.
	\end{align}
	Taking the power \(1/p\), we obtain
	\begin{equation}
		\label{eq:fixed-time-space-error-rate}
		\operatorname{E}_{x,\pi}\left[
		\left|
		W^+_{\gamma_\varepsilon(t)}
		-
		W^+_{\gamma_0(t)}
		\right|^p
		\right]^{1/p}
		\le
		\operatorname{E}_x^W\left[[W^+]_{\theta,T}^{pq'}\right]^{1/(pq')}
		\operatorname{E}_{x,\pi}\left[
		\Delta_\varepsilon(t)^{p\theta q}
		\right]^{1/(pq)}.
	\end{equation}
	By Proposition~\ref{prop:Holder},
	\[
	\sup_{x\in\overline D}
	\operatorname{E}_x^W\left[[W^+]_{\theta,T}^{pq'}\right]
	<\infty,
	\]
	while \eqref{eq:fixed-time-gamma-La-rate}, with
	\(a=p\theta q\), gives
	\[
	\sup_{x\in\overline D}
	\sup_{0\le t\le T}
	\operatorname{E}_{x,\pi}\left[
	\Delta_\varepsilon(t)^{p\theta q}
	\right]^{1/(pq)}
	\le
	C\varepsilon^{\theta/4}.
	\]
	Therefore,
	\[
	\sup_{x\in\overline D}
	\sup_{0\le t\le T}
	\operatorname{E}_{x,\pi}\left[
	\left|
	W^+_{\gamma_\varepsilon(t)}
	-
	W^+_{\gamma_0(t)}
	\right|^p
	\right]^{1/p}
	\le
	C\varepsilon^{\theta/4}.
	\]
	Letting \(\theta\) approach \(1/2\), any \(0<\beta<1/8\) can be chosen with
	\[
	\beta<\frac{\theta}{4}.
	\]
	This proves \eqref{eq:fixed-time-process-rate}.

	\medskip
	\noindent\emph{Step 3: uniform-in-time error.}
	Fix \(0<\beta<1/8\). Choose \(0<\zeta<1/2\) and \(\theta\in(0,1/2)\) such that
	\begin{equation}
		\label{eq:choose-theta-zeta-sticky}
		\beta<\frac{\theta\zeta}{2}.
	\end{equation}
	By the definition of the H\"older seminorm and
	\eqref{eq:fixed-time-inverse-bound},
	\[
	\sup_{t\in[0,T]}
	\left|
	W^+_{\gamma_\varepsilon(t)}
	-
	W^+_{\gamma_0(t)}
	\right|
	\le
	[W^+]_{\theta,T}
	\sup_{t\in[0,T]}
	|\gamma_\varepsilon(t)-\gamma_0(t)|^\theta.
	\]
	Since \(\gamma_0(t)\in[0,T]\),
	\[
	\sup_{t\in[0,T]}\Delta_\varepsilon(t)
	\le
	\sup_{r\in[0,T]}
	\left|
	\int_0^r
	\bigl(\rho(\alpha_{s/\varepsilon})-\overline\rho\bigr)\,dL_s
	\right|.
	\]
	Applying~\eqref{eq:local-time-averaging-assumption-max}, uniformly in the
	starting point, gives
	\begin{equation}
		\label{eq:uniform-gamma-L2-rate}
		\sup_{x\in\overline D}
		\operatorname{E}_{x,\pi}\left[
		\sup_{t\in[0,T]}\Delta_\varepsilon(t)^2
		\right]
		\le
		C\varepsilon^\zeta.
	\end{equation}
	Consequently, for every \(a\in(0,2]\),
	\begin{equation}
		\label{eq:uniform-gamma-La-rate}
		\sup_{x\in\overline D}
		\operatorname{E}_{x,\pi}\left[
		\sup_{t\in[0,T]}\Delta_\varepsilon(t)^a
		\right]
		\le
		C\varepsilon^{a\zeta/2}.
	\end{equation}
	Let \(p\in[1,2]\), choose \(r>1\) close enough to \(1\) that
	\(p\theta r\le2\), and let \(r'\) be its conjugate exponent.
	H\"older's inequality and Proposition~\ref{prop:Holder} give
	\[
	\begin{aligned}
		&\operatorname{E}_{x,\pi}\left[
		\sup_{t\in[0,T]}
		\left|
		W^+_{\gamma_\varepsilon(t)}
		-
		W^+_{\gamma_0(t)}
		\right|^p
		\right]^{1/p}\\
		&\qquad\le
		\operatorname{E}_x^W\left[[W^+]_{\theta,T}^{pr'}\right]^{1/(pr')}
		\operatorname{E}_{x,\pi}\left[
		\sup_{t\in[0,T]}
		\Delta_\varepsilon(t)^{p\theta r}
		\right]^{1/(pr)}.
	\end{aligned}
	\]
	Hence,
	\[
	\sup_{x\in\overline D}
	\operatorname{E}_{x,\pi}\left[
	\sup_{t\in[0,T]}
	\left|
	W^+_{\gamma_\varepsilon(t)}
	-
	W^+_{\gamma_0(t)}
	\right|^p
	\right]^{1/p}
	\le
	C\varepsilon^{\theta\zeta/2}.
	\]
	By \eqref{eq:choose-theta-zeta-sticky}, the last term is
	\(O(\varepsilon^\beta)\). This proves \eqref{eq:uniform-process-rate}.

\label{thm:annealed-sticky-elastic-semigroup}
		The family \((\mathcal S_t)_{t\ge0}\) is a strongly continuous contraction
		semigroup on \(C(\overline D\times S)\).

		Let
		\begin{equation}
			\label{eq:D0-definition}
			\mathcal D_0
			:=
			\left\{
			\begin{array}{l}
				\Phi\in C(\overline D\times S):
				\Phi_i\in C^2(\overline D)\text{ for every }i\in S,\text{ and}\\
				\partial_{\mathbf n}\Phi_i
				+\kappa_i\Phi_i
				+\rho_i
				\left(
				\dfrac12\Delta\Phi_i
				+\displaystyle\sum_{j\in S}q_{ij}\Phi_j
				\right)
				=0
				\quad\text{on }\partial D,\ i\in S
			\end{array}
			\right\}.
		\end{equation}
		Then \(\mathcal D_0\subset D(\mathcal G)\), where \(\mathcal G\) is the
		generator of \((\mathcal S_t)_{t\ge0}\), and for every
		\(\Phi\in\mathcal D_0\),
		\begin{equation}
			\label{eq:switching-generator-abstract}
			(\mathcal G\Phi)(x,i)
			=
			(\mathcal L\Phi)_i(x)
			\qquad x\in D.
		\end{equation}

		We only claim the inclusion $\mathcal D_0\subset D(\mathcal G)$; no core
		property or converse characterization of the generator domain is needed.

		For every \(\Phi\in C(\overline D\times S)\), the function
		\begin{equation}
			\label{eq:u-semigroup-definition}
			u(t,x,i):=(\mathcal S_t\Phi)(x,i)
		\end{equation}
		is the unique mild solution of the abstract Cauchy problem
		\begin{equation}
			\label{eq:abstract-cauchy-problem}
			\frac{d}{dt}u(t)=\mathcal Gu(t),
			\qquad
			u(0)=\Phi.
		\end{equation}
		If, additionally, $u$ is continuously differentiable in time with values in $C(\overline D\times S)$ and $u(t)\in\mathcal D_0$, then $u$ solves the coupled
		backward system
		\begin{equation}
			\label{eq:coupled-backward-system}
			\partial_tu(t,x,i)
			=
			\frac12\Delta_xu(t,x,i)
			+
			\sum_{j\in S}q_{ij}u(t,x,j),
			\qquad x\in D,
		\end{equation}
		with sticky-elastic boundary condition
		\begin{equation}
			\label{eq:coupled-sticky-elastic-bc}
			\partial_{\mathbf n}u(t,\xi,i)
			+\kappa_i u(t,\xi,i)
			+\rho_i
			\left(
			\frac12\Delta_xu(t,\xi,i)
			+\sum_{j\in S}q_{ij}u(t,\xi,j)
			\right)
			=0,
			\qquad \xi\in\partial D,
		\end{equation}
		and initial datum
		\begin{equation}
			\label{eq:coupled-initial-condition}
			u(0,x,i)=\Phi(x,i).
		\end{equation}
		Using the interior equation, the same boundary condition reads
		\begin{equation}
			\label{eq:dynamic-wentzell-bc}
			\partial_{\mathbf n}u(t,\xi,i)
			+\kappa_i u(t,\xi,i)
			+\rho_i\partial_tu(t,\xi,i)
			=0.
		\end{equation}

\label{thm:forward_quenched}
		Let \(\mu_0\in\mathcal M(\overline D)\), and define
		\((\mu_t^\alpha)_{t\ge0}\) by
		\eqref{eq:quenched-forward-duality}. Then the following properties hold.

		\begin{enumerate}
			\item For every \(t\ge0\),
			\begin{equation}
				\label{eq:forward-tv-contraction}
				\|\mu_t^\alpha\|_{\mathrm{TV}}
				\le
				\|\mu_0\|_{\mathrm{TV}}.
			\end{equation}
			If \(\kappa\equiv0\), then total mass is conserved.

			\item The map \(t\mapsto\mu_t^\alpha\) is narrowly continuous.

			\item For every \(f\in C^2(\overline D)\),
			\begin{equation}
				\label{eq:quenched-forward-dynkin}
				\begin{aligned}
					&\int_{\overline D}f(y)\,\mu_t^\alpha(dy)
					-
					\int_{\overline D}f(y)\,\mu_0(dy)
					\\
					&=
					\int_{\overline D}
					\operatorname{E}_x\!\left[
					\frac12
					\int_0^{\gamma^\alpha(t)}
					H^\alpha_s
					\Delta f(W_s^+)\,ds
					\right]\mu_0(dx)
					\\
					&\quad
					-
					\int_{\overline D}
					\operatorname{E}_x\!\left[
					\int_0^{\gamma^\alpha(t)}
					H^\alpha_s
					\left(
					\partial_{\mathbf n}f
					+\kappa(\alpha_s)f
					\right)(W_s^+)\,dL_s
					\right]\mu_0(dx).
				\end{aligned}
			\end{equation}

			\item If \(f\in\mathcal D_\alpha\), then
			\begin{equation}
				\label{eq:weak-forward-equation}
				\int_{\overline D}f\,d\mu_t^\alpha
				-
				\int_{\overline D}f\,d\mu_0
				=
				\frac12
				\int_0^t
				\int_{\overline D}\Delta f(y)\,
				\mu_s^\alpha(dy)\,ds.
			\end{equation}
			Equivalently,
			\begin{equation}
				\label{eq:weak-forward-derivative}
				\frac{d}{dt}
				\int_{\overline D}f\,d\mu_t^\alpha
				=
				\frac12
				\int_{\overline D}\Delta f\,d\mu_t^\alpha
			\end{equation}
			for every \(t\ge0\).

			\item More generally, let
			\(\varphi\in C^1([0,T];C(\overline D))\) satisfy
			\[
			\varphi(t,\cdot)\in\mathcal D_\alpha,
			\qquad
			\Delta\varphi\in C([0,T]\times\overline D).
			\]
			Then
			\begin{equation}
				\label{eq:weak-forward-time-dependent}
				\begin{aligned}
					&\int_{\overline D}\varphi(T,x)\,\mu_T^\alpha(dx)
					-
					\int_{\overline D}\varphi(0,x)\,\mu_0(dx)
					\\
					&\qquad
					=
					\int_0^T
					\int_{\overline D}
					\left(
					\partial_t\varphi(t,x)
					+\frac12\Delta\varphi(t,x)
					\right)
					\mu_t^\alpha(dx)\,dt.
				\end{aligned}
			\end{equation}
		\end{enumerate}

\label{prop:Holder}
		For every \(\theta\in(0,1/2)\), \(q\ge1\), and \(T>0\), there exists a
		constant \(C(D,\theta,q,T)>0\) such that
		\begin{equation}
			\label{eq:holder-moment-assumption}
			\sup_{x\in\overline D} \operatorname{E}_x\left[
			[W^+]_{\theta,T}^q + [L]_{\theta,T}^q
			\right]
			\le C(D,\theta,q,T).
		\end{equation}

\label{prop:LTA}
	Under the assumptions of Section~\ref{ssec:notation}, let
	\(h:S\to\mathbb R\) be bounded and centered with respect to \(\pi\).
	Then, for every \(T>0\), the following estimates hold uniformly in
	\(x\in\overline D\) and \(i\in S\):
	\begin{enuroman}
		\item\label{item:LTA_marginal}
		For every \(\varepsilon\in(0,1]\) and every \([0,T]\)-valued random
		time \(\tau\) measurable with respect to the reflected Brownian path,
		\begin{equation}
			\label{eq:random-time-local-time-averaging}
			\sup_{\substack{x\in\overline D\\ i\in S}}
			\operatorname{E}_{x,i}\left[
			\left|
			\int_0^\tau h(\alpha_{s/\varepsilon})\,dL_s
			\right|^2
			\right]
			\le C_T(h)\varepsilon^{1/2};
		\end{equation}

		\item\label{item:LTA_sup}
		For every \(\varepsilon\in(0,1]\),
		\begin{equation}
			\label{eq:maximal-local-time-averaging-log}
			\sup_{\substack{x\in\overline D\\ i\in S}}
			\operatorname{E}_{x,i}\left[
			\sup_{0\le t\le T}
			\left|
			\int_0^t h(\alpha_{s/\varepsilon})\,dL_s
			\right|^2
			\right]
			\le
			C_{T,h}\varepsilon^{1/2}
			(1+|\log\varepsilon|)^2.
		\end{equation}
		Consequently, for every \(0<\zeta<1/2\), there exists
		\(C_{T,h,\zeta}<\infty\) such that
		\begin{equation}
			\label{eq:maximal-local-time-averaging}
			\sup_{\substack{x\in\overline D\\ i\in S}}
			\operatorname{E}_{x,i}\left[
			\sup_{0\le t\le T}
			\left|
			\int_0^t h(\alpha_{s/\varepsilon})\,dL_s
			\right|^2
			\right]
			\le C_{T,h,\zeta}\varepsilon^\zeta.
		\end{equation}
	\end{enuroman}
